window.PB_TEXTS=window.PB_TEXTS||{};window.PB_TEXTS["PB-3764CB4328730FD7"]={"schemaVersion": 1, "documentId": "PB-3764CB4328730FD7", "title": "Neschers Kommendörsvisa – Bengt Gustaf Jonshult, Acta Bricolensia 9 2025", "sourceSha256": "3764cb4328730fd708fcd518658d47dbf62f28eb3e1b080423c0e98d27b4fbad", "method": "Poppler pdftotext -layout; existing PDF text layer; no new OCR", "extractedAt": "2026-10-05T13:27:51.456882+00:00", "pages": [{"pdfPage": 1, "printedPage": null, "text": "Acta Bricolensia\n                        9/2025\n\n         Neschers Kommendörsvisa\n                            av\n               Bengt Gustaf Jonshult\n\n\n\n\nActa Bricolensia är Sällskapet Par Bricoles serie med digitala\n   artiklar publicerade av Den Bacchanaliska Akademien\n\n                       Redaktion\n   Christer Alexandersson, Dan Ekström, Hans Gillgren,\n                Mats Hayen och Peter Lind"}, {"pdfPage": 2, "printedPage": null, "text": "", "ocrText": "", "ocrSegments": [""], "autoTextLayer": "original", "machineAssessment": {"confidence": 0.0, "needsReview": true, "automaticSplit": false, "engine": "Tesseract 5.5.3; LSTM; psm 3", "version": "batch-v2", "sourceSha256": "3764cb4328730fd708fcd518658d47dbf62f28eb3e1b080423c0e98d27b4fbad", "modelHashes": {"Fraktur": "29a867a25f1b00a5e9827356582515619d5102688bc1d14015789c78941116ee", "swe": "360303308aa5d4a912ac3b3637691152b7532d9bd6e960639db1affb83db7ea9"}, "languages": ["swe"], "selection": "confidence-and-coverage-heuristic; not proofreading", "createdAt": "2026-10-05T14:04:09.994969+00:00", "statisticsParser": "tsv-quote-none-v1; prior row counts checked"}}, {"pdfPage": 3, "printedPage": null, "text": "Neschers Kommendörsvisa\nBengt Gustaf Jonshult\n\n\n\n\nEtt återkommande musikaliskt inslag i Par Bricole är den så\nkallade Kommendörsvisan.\n   Traditionen att med sång hylla Sällskapets kommendörer\nsträcker sig på det idémässiga planet tillbaka till Bellmans\nordensfantasi Bacchi Orden från 1760-talet.\n   En stor del av skaldens äldre bacchanaliska texter tillkom\ninom ramen för Bacchi Orden. På samma sätt tillhör många\nav hans bacchanaliska visor från 1780 och framåt livet i Par\nBricole. Den burleska komiken, som inte sällan överskred\ngränsen till vad som kan uppfattas som lågt och plumpt, var\nframför allt det som tidigt befäste Bellmans ställning som\nvisskald – och som i viss mån lockade hans goda vänner att\nförvandla Bacchi Orden till en verklig sällskapsorden.\n   I Par Bricoles arkiv finns den allra första kommendörs-\nvisan, författad enligt Daniel Georg Nescher av Carl Israel\nHallman:\n\n  När Moses ur Egypten drog\n  Och genom Öknen wandra,\n  Han M:s på alla Flickor tog;\n  Fast Aron därpå klandra.\n  Hwar Flicka log, när k…n stog;\n  Det gick just till, som i Städer:\n  Och minnet utaf denna färd,\n\n                                         Acta Bricolensia 9/2025   3"}, {"pdfPage": 4, "printedPage": null, "text": "Hwar trogen Själ ännu gläder.\n      Wahrhaftig, wir sollen nun Trinken! ://:\n      Fallerallerara fallera ://:\n      Das Wasser bleibt an den Linken! ://:\n\n      Wi ha sedt Skutor många nog;\n      Af wattnet platt förgiöras;\n      Pharaos här i wattnet Dog,\n      Och Petersburg förstöras.\n      Men ägta Bröder Par Bricole,\n      De lärt att wattnet hata;\n      De känna wärdet af en Bål,\n      Och Pounchen aldrig rata.\n      Wahrhaftig, wir sollen nun Trinken! ://: etc.\n\n    I arkivet finns två avskrifter av kommendörsvisan.\n        Den första varianten (på bild till höger), bär titeln ”Äldste\n    Commendeurs Wisan” och den andra (bild på nästa sida),\n    bär titeln ”Den Första Commendeurs Wisan”.\n        Varianten till höger synes vara förd av Neschers hand,\n    med typiskt noggrann numrering och paginering (och med\n    angivande av författarens namn: C. I. Hallman).\n        Den andra varianten har undgått en hel del ändringar, där\n    det uppenbarligen har funnits vissa dubier med rad fem. I rad\n    åtta har ordet ”Christen” ersatts med ”Trogen” och i den an-\n    dra versen har Petersburg fått ge vika åt Lissabon (till saken\n    hör att båda städerna drabbades hårt av översvämningar).\n        En gissning är att den andra varianten är den äldsta – till\n    synes tillkommen under mer improviserade omständigheter.\n        Värt att nämnas är att den första versen i båda versioner-\n    na, till stora delar, överensstämmer med en visa attribuerad\n    till Bellman i en avskrift från 1765:\n\n      När Moses ur Egypten drog,\n      Och genom öknen vandra,\n      Israels barn had’ manna nog,\n\n4   Bengt Gustaf Jonshult • Neschers Kommendörsvisa"}, {"pdfPage": 5, "printedPage": null, "text": "Den äldsta Kommendörsvisan. Par Bricoles arkiv.\nFoto: Mats Hayen.\n\n\n\n\n                                           Acta Bricolensia 9/2025   5"}, {"pdfPage": 6, "printedPage": null, "text": "Men lika fullt de klandra.\n      De vämdes vid så löser mat,\n      Det var för mager föda.\n      Jag vet, at de af drufvors saft\n      Sig hellre velat göda.\n      So eben bist du, wahrhaftig,\n      Fallerallerarallei\n      Dass Wasser tut mir nicht kraftig.\n\n    Detta är i sig inget tecken på litterär stöld, utan visar på hur\n    texter under 1700-talet kunde traderas, förändras och imi-\n    teras på ett tämligen fritt sätt. Ett tänkbart alternativ är för\n    övrigt att författaren till den första kommendörsvisan är just\n    Carl Michael Bellman. Något som talar för detta är textens\n    andra vers. Den startar med raderna:\n\n      Wi ha sedt Skutor många nog\n      Af wattnet platt förgiöras.”\n\n    De flesta dryckesvisor har sin egen typologi och i många fall\n    utvecklar de också egna troper. Den sista versen av Fred-\n    mans sång 10 (Supa klockan över tolv) avslutas till exempel\n    med orden:\n\n      Och oss sedan döda, I det våta röda.\n\n    ... där döden är en metafor för den yttersta lycksaligheten\n    som uppnås genom berusning och det våta röda står givetvis\n    för det röda vinet. Men det var i dryckesvisetraditionen även\n    en allusion till Röda havet, i vilket vatten Faraos här i någon\n    mening dog.\n        I en svensk variant på den franska dryckesvisan ”La Mer\n    Rouge en sa couleur” från 1600-talet, heter det:\n      När som Pharao med sin här\n      kom til hafwet röda\n\n6   Bengt Gustaf Jonshult • Neschers Kommendörsvisa"}, {"pdfPage": 7, "printedPage": null, "text": "Den första Kommendörsvisan. Par Bricoles arkiv.\nFoto: Mats Hayen.\n\n\n\n\n                                           Acta Bricolensia 9/2025   7"}, {"pdfPage": 8, "printedPage": null, "text": "till drick stod deras begär,\n      hwaraf de blefwo döda.\n\n    Det våta röda och kopplingen till Farao gav Bellman även\n    stoff till en hel dryckesvisa (här ur en avskrift från 1767):\n\n      Kiäre bröder ! Drickom Mosis skål,\n      Han är döder, men i denna Bål,\n      wi hans namn uplifwa,\n      oss på resan gifwa,\n      I det friska, friska röda Haf:\n      denna Bischofs slefwen,\n      för wår wärd är blifwen\n      Mosis staf:\n      Hafwet han med denna stafwen delar;\n      Pharao han kom med alt gewalt;\n      Konsten honom felar,\n      Han med Wagn och selar,\n      Plumpa neder, som en tunna malt.\n      Lika godt må wara , wi torr skodda fara, Marche öfwer alt.\n\n    Moses, vattnet, vinet, bålet, havet och Farao är återkomman-\n    de troper, både i Kommendörsvisans andra vers och i Carl\n    Michael Bellmans visa från 1765. Texternas andemening är\n    densamma.\n       I samband med att det libertinistiska 1700-talet övergick\n    i det romantiska 1800-talet ägde en allmän smakförändring\n    rum. Par Bricoles äldsta Kommendörsvisa uppfattades som\n    föråldrad och uppdraget att författa en ny Kommendörsvisa\n    gick till Daniel Georg Nescher:\n\n      Bacchi Lofsång\n\n      Dygden vi dyrka,\n      måttlighet yrka,\n      ordning och styrka\n      fästa vårt band!\n\n8   Bengt Gustaf Jonshult • Neschers Kommendörsvisa"}, {"pdfPage": 9, "printedPage": null, "text": "Vänner vi pröva!\n  Munterhet öva!\n  Dem, som behöva,\n  räckes vår hand!\n  Främling! Oss gläder,\n  Bacchus tillstäder,\n  att Du inträder\n  uti hans hus!\n  Vill du nu svära\n  följa dess lära,\n  lagom förtära?\n  Skall Du få ljus.\n\nMed betoning på dygd, måttlighet, ordning, munterhet och\n”lagom förtära” ingick den nya Kommendörsvisan som en\ndel av Neschers reformarbete i Par Bricole.\n   I 1799 års statuter, till stor del är utformade av Nescher,\ndeklareras att:\n\n  Inbördes Wänskap, Aktning och förtroende äro detta Säll-\n  skaps hufvudsakelige föremål. At under muntra och an-\n  ständiga tidsfördrif lindra lifvets besvärligheter och torftiga\n  medmenniskors nöd” och för att bli en värdig medlem krävs\n  ”anständig Qvickhet och munterhet, ett ömt, medlidande och\n  vänfast hjerta, samt stadga och måttelighet i alla nöijen.”\n\nVår tids Kommendörsvisa bygger vidare på Daniel Georg\nNeschers programförklaring:\n\n  Munterhet, ordning, förtrolighet, styrka,\n  veta förena på sätt som sig bör.\n  Arbeta nitiskt och Bacchus rätt dyrka\n  Tillhör varenda Bricolekommendör.\n  Uslingar hjälpa som nöden betunga\n  Vänskap och aktning bevisa med flit.\n  Måtteligt dricka och anständigt sjunga\n  får man sig lära i Bricoleriet.\n\n                                              Acta Bricolensia 9/2025   9"}, {"pdfPage": 10, "printedPage": null, "text": "Sådana plikter, Så ärbara seder\n       Böra värderas Utav en och var.\n       Därföre till kommendörernas heder\n       Fatten pokalerna, Safter ej spar.\n       Sjungom och låtom oss armbågen höja,\n       Skål för var tratt i ett rosenrött band.\n       Kyssen och hjärtat vår vänskap skall röja,\n       Troheten fästas med slaget i hand.\n\n     Det är en annan ton i Neschers kommendörsvisa, än i de\n     tidiga backanaliska kväden som Bellman och Hallman med\n     flera skrivit i exklusivt manliga sällskap, på klubbar eller i\n     Par Bricolekretsar.\n        Att indela visorna i distinkt skilda grupper efter den tänkta\n     publiken, låter sig emellertid knappast göra.\n        Både den manliga och kvinnliga publiken på 1700-talet\n     hade ingalunda någon prydhet – varken in Baccho eller in\n     Venere. Snarare kan man tala om en allmän förskjutning\n     från frihetstidens smak till det mer förfinade gustavianska\n     samhället. Dryckesvisans grundfunktion är och förblir den-\n     samma oavsett miljöbyten och sociala förändringar.\n        Även Bellman anammade den mer ”återhållsamma sti-\n     len”. I en Par Bricolesång daterad den 15 maj 1786 deklarerar\n     skalden:\n       Vårt göromål på denna vår dag\n       Är at bekräfta vår åldriga lag\n       Vinet till ära i måttliga mått,\n       Hedra bricoler och önska dem godt\n\n     Slutligen några ord om den musikaliska inramningen.\n         Melodin till den första kommendörsvisan är okänd (likaså\n     till den bellmanska förlagan), men Neschers visa ”Bacchi\n     Lofsång”, ska, uppger källorna, sjungas på en melodi av\n     Wolfgang Amadeus Mozart.\n\n10   Bengt Gustaf Jonshult • Neschers Kommendörsvisa"}, {"pdfPage": 11, "printedPage": null, "text": "”Thema med 9 variationer af Mozard” trycktes i Olof Åhlströms\n  Musikaliskt Tidsfördrif 1791 (Nr 10, 11 och 12). Det var en tid-\n  skrift som utgavs 1789–1834 i Stockholm.\n\n\n   Musikstycket ”Thema med 9 variationer af Mozard”\ntrycktes i Olof Åhlströms Musikaliskt Tidsfördrif 1791.\n   Olof Åhlström, som var medlem i Par Bricole, hade 1790–\n1791 redigerat Fredmans epistlar och Fredmans sånger.\n   Åhlström och Nescher hade tidigare samarbetat, bland an-\nnat i samband med utgivningen av epistlarna, då Nescher\nägde en tidig avskrift av de femtio första epistlarna.\n   Troligtvis presenterade Olof Åhlström Mozarts melodi\nför Daniel Georg Nescher.\n   Grundtemat, med sin relativt enkla uppbyggnad (variatio-\nnerna är dock betydligt mer avancerade), passade perfekt för\nen ny Kommendörsvisa i Par Bricole.\n\n                                               Acta Bricolensia 9/2025   11"}, {"pdfPage": 12, "printedPage": null, "text": "Mozart komponerade dock inte melodin.\n        I själva verket skrevs den drygt tjugo år tidigare av den\n     franska kompositören Nicolas Dezède. Den ingår som ari-\n     ett i operetten Julie från 1772, Arietten i fråga förekommer i\n     början på Akt 2, ”Lison dormait dans un bocage”.\n        Mozart ska ha sett pjäsen i Paris år 1778 och nedtecknat\n     temat. Den räknas bland hans större variationsuppsättningar,\n     både på grund av sin omfattning (den är nästan tjugo minuter\n     lång) och i sitt breda och färgstarka omfång (KV 264).\n        Neschers Kommendörsvisa är sålunda en fri adaption från\n     Mozart, men konturerna på visan ”Lison dormait” är tydliga.\n        Märkligt nog finns det en helt annan text, skriven av Hall-\n     man, som även den kan sjungas på Dezèdes melodi. Texten\n     återfinns i Hallmans teaterstycke Finkels Parentations-Act\n     från 1777:\n\n       Bacchus är redlig,\n       Torstig och fredlig\n       Lefwer så makligt och fettmar i söl;\n       Röd uti synen\n       Och ögonbrynen\n       Blötas och frodas af svett och af öl.\n       Bacchus är lustig,\n       Fucktig och mustig,\n       Röker sin rulltobak, grinar åt soln,\n       Han sig förlustar\n       Stånkar och pustar,\n       Til des han hwimlar och tumlar af stoln.\n\n     Säkerligen bara en slump. Under alla omständigheter utgör\n     Neschers kommendörsvisa (och dagens version) en av Par\n     Bricoles allra äldsta sångtraditioner.\n       Visorna har sjungits intakta i över 220 år.\n\n\n\n12   Bengt Gustaf Jonshult • Neschers Kommendörsvisa"}]}
;
